// Auto-filter: only show events from today onwards — sorted chronologically
const _MOIS = {jan:0,fév:1,mar:2,avr:3,mai:4,juin:5,juil:6,août:7,sep:8,oct:9,nov:10,déc:11};
function _eventDate(e) {
  const p = e.date.trim().split(' ');
  const m = _MOIS[p[2]];
  return m !== undefined ? new Date(e.year || new Date().getFullYear(), m, parseInt(p[1])) : null;
}
const _today = new Date(); _today.setHours(0, 0, 0, 0);
function _eventHour(e) {
  const t = (e.time || '').replace(/\s/g, '');
  const m = t.match(/^(\d{1,2})h(\d{2})?/);
  if (m) return parseInt(m[1]) * 60 + (m[2] ? parseInt(m[2]) : 0);
  // Horaires en toutes lettres (heure non publiée par la source) : on leur donne
  // une place crédible dans la journée pour que le tri reste chronologique.
  const mot = t.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
  if (mot === 'enjournee') return 11 * 60;   // en journée → 11h
  if (mot === 'ensoiree')  return 21 * 60;   // en soirée  → 21h
  return 9999;                               // inconnu : en fin de journée
}

// Tri STRICTEMENT CHRONOLOGIQUE à l'intérieur de chaque journée (2 août 2026).
// Avant, trois étages reléguaient les fiches annuaire puis les apéros/soirées APRÈS
// tout le reste : un happy hour de 15h30 s'affichait donc après un concert de 20h30,
// et le cinéma de 10h30 après la soirée. On trie désormais uniquement par heure.
function _sortTier() { return 0; }

// Carte « Mettre à jour » : UNE seule fiche, datée du JOUR (re-datée à chaque build),
// en 1ère position à l'ouverture — mais PAS répétée en tête de chaque jour.
const _JJ = ['Dim','Lun','Mar','Mer','Jeu','Ven','Sam'];
const _MM = ['jan','fév','mar','avr','mai','juin','juil','août','sep','oct','nov','déc'];
const _nowUpd = new Date();
const _updateCard = { id: 999900, year: _nowUpd.getFullYear(), cat: "MISE À JOUR", date: `${_JJ[_nowUpd.getDay()]} ${_nowUpd.getDate()} ${_MM[_nowUpd.getMonth()]}`, time: "00h00", title: "METS À JOUR\nMONAC'OUT\nVERSION 2.1", subtitle: "App Store · Monac'Out", desc: "Une nouvelle version de Monac'Out est disponible ! Mets à jour l'app depuis l'App Store pour la connexion simplifiée, tes amis et les dernières améliorations.", descEn: "A new version of Monac'Out is available! Update from the App Store for simpler sign-in, friends and the latest improvements.", free: true, hot: true, fallback: "linear-gradient(150deg,#0F1D3A,#243B66,#7B2D26)", accent: "#7B2D26", emoji: "✨", link: "https://apps.apple.com/fr/app/monacout/id6774785049", source: "Monac'Out", quarter: "Monaco" };

// Une attraction EN COURS (ongoing:true) est ouverte tous les jours jusqu'à `until`.
// Elle ne porte pourtant qu'UNE date dans le fichier. Tant qu'on se reposait sur le
// script de nuit pour la redater, elle sortait du fil au moindre passage manqué.
// On la garde désormais tant que sa date de fin n'est pas passée : elle est là chaque
// jour entre l'ouverture et la fermeture, script ou pas.
export function _encoreOuvert(e, ref) {
  if (!e.ongoing || !e.until) return false;
  const fin = new Date(e.until + "T00:00:00");
  return !isNaN(fin) && fin >= ref;
}

export const ALL_EVENTS = [..._RAW
  .filter(e => { const d = _eventDate(e); return d && (d >= _today || _encoreOuvert(e, _today)); })
  .sort((a, b) => {
    const diff = _eventDate(a) - _eventDate(b);
    if (diff !== 0) return diff;
    const at = _sortTier(a), bt = _sortTier(b);
    if (at !== bt) return at - bt;
    return _eventHour(a) - _eventHour(b);
  })];
